def icon_svg(name: str, cls: str = "", size: int = 18) -> str:
    d = ICONS.get(name, ICONS["_default"])
    return (
        f'<svg class="{cls}" width="{size}" height="{size}" viewBox="0 0 24 24" '
        f'fill="none" stroke="currentColor" stroke-width="1.8" '
        f'stroke-linecap="round" stroke-linejoin="round">{d}</svg>'
    )
